 function bind(){
  const story=Number(params.get('story'));
  if(route==='settings/journeys'&&Number.isInteger(story)&&story>=1&&story<=stories.length){const [title,to]=stories[story-1];main.querySelector('.page-heading').insertAdjacentHTML('afterend',note('US'+String(story).padStart(2,'0')+' · Selected story',esc(title),to,'Open this scenario'));}
  main.querySelectorAll('[data-scenario]').forEach(el=>el.onchange=()=>{location.hash=query(el.dataset.scenario,el.value);});
  const input=main.querySelector('#task-search');
  if(input){const update=()=>{let n=0;main.querySelectorAll('[data-search]').forEach(card=>{card.hidden=!card.dataset.search.includes(input.value.trim().toLowerCase());if(!card.hidden)n++;});document.querySelector('#no-results').hidden=n>0;document.querySelector('#search-status').textContent=n+' matching tasks';};const clear=()=>{input.value='';update();input.focus();};input.oninput=update;input.form.onsubmit=e=>{e.preventDefault();update();};input.form.onreset=e=>{e.preventDefault();clear();};main.querySelector('[data-clear-tasks]').onclick=clear;}
  const form=main.querySelector('#order-filters');
  if(form){const update=()=>{retained.q=form.elements.q.value;retained.status=form.elements.status.value;const rows=orders.filter(o=>(retained.status==='All'||o.status===retained.status)&&[o.id,o.person,o.art].join(' ').toLowerCase().includes(retained.q.toLowerCase()));document.querySelector('#order-count').textContent=rows.length+' matching orders';document.querySelector('#order-results').innerHTML=rows.length?table('Filtered orders',['Order / customer','Artwork','Stage / payment','Owner & due','Open'],rows.map(o=>[o.id+'<br>'+o.person,esc(o.art),pill(o.stage)+'<br>'+pill(o.payment),o.owner+' · '+o.due,link('orders/record?id='+o.id,'Open order')])):`<div class="empty"><h2>No matching orders</h2><p>Clear or adjust filters to see the sample records.</p></div>`;};form.oninput=update;form.onsubmit=e=>{e.preventDefault();update();};form.onreset=e=>{e.preventDefault();form.elements.q.value='';form.elements.status.value='All';update();};update();}
 }
 const navLink=key=>`<a href="#${key}" data-area="${key}">${svg(key)}<span>${areas[key]}</span></a>`;
 document.querySelector('#navigation').innerHTML=['orders','customers','products','support','reports','tools'].map(navLink).join('');
 document.querySelector('#settings-navigation').innerHTML=navLink('settings');
