 const aliases={analytics:'reports','orders/attention':'orders','orders/review':'orders/payments','customers/directory':'customers','products/catalogue':'products','support/inbox':'support','tools/team':'settings/access','tools/services':'settings/connections','tools/policies':'settings/rules','tools/readiness':'settings/readiness','tools/guides':'settings/guides','analytics/audit':'settings/activity','analytics/sales':'reports/sales','analytics/performance':'reports/performance'};
 function render(){const raw=location.hash.slice(1)||'orders',i=raw.indexOf('?');route=i<0?raw:raw.slice(0,i);params=new URLSearchParams(i<0?'':raw.slice(i+1));route=aliases[route]||route;area=route.split('/')[0];document.querySelectorAll('[data-area]').forEach(a=>{if(a.dataset.area===area)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  const body=Object.hasOwn(screens,route)?screens[route]():heading('Page not found','This wireframe destination does not exist.',`<div class="empty">${link('orders','Return to Today','button secondary-button')}</div>`);
  main.innerHTML=(tabs[area]?`<nav class="section-tabs" aria-label="${areas[area]} pages">${tabs[area].map(([to,title])=>`<a href="#${to}"${route===to?' aria-current="page"':''}>${title}</a>`).join('')}</nav>`:'')+body;
  document.title=(main.querySelector('h1')?.textContent||'Admin')+' · Aalishaan wireframe W1';bind();main.querySelector('h1')?.focus({preventScroll:true});window.scrollTo(0,0);
 }
